-- Loot rates far above the live game's, on 665 loot tables: 3662 rows set to the rate players measure on live.
-- 2026_11_25_24_world_everlake_live_loot_rates.sql: written by hand from the tracker's kept facts (2026-11-25), after the Galestriders on Zephras Isle
-- (2026_11_25_23) showed loot rates many times the live game's.
--
-- Two of the core fork's imports set most of these rates: QuestieDB's (rows marked 'QuestieDB v1.1.x') and the
-- 2026-11 sniffs ('Forever live drop ...', every item seen once in a few kills at a flat rate). Icy Veins' WoW Forever
-- database (https://db.icy-veins.com/wow-forever/: players' addons on live) records each creature's drops from its own
-- kills. A row here is one where:
--   - the realm's chance is at least three times Icy Veins' rate for that creature and item, and at least 0.3 above it;
--   - the row is not a quest drop (QuestRequired 0) and came from one of those two imports;
--   - the creature stands somewhere and its Icy Veins record is well sampled: its rarest recorded drop is at 0.33% or
--     less, so it rests on some 300 kills or more (an item seen once in N kills shows as 100/N %). 109 rows on thinly
--     recorded creatures are left as they are.
-- The new chance is Icy Veins' rate, to two decimals, at least 0.01. Each row changes only while it still holds a
-- chance at least three times the new one, so a later fix is never undone. Where the same item stands twice in one
-- loot table (a QuestieDB row and a sniff row), the sniff row goes first, so the item is not counted twice.
--
-- Typical: low-level grey armour at 3-5% where the live game gives 0.5-0.8%; level-20 to level-40 greens at 1-6% where
-- it gives 0.02-0.2%. Of the 3662 rows, most stood at 1% or more.
--
-- Running it again changes nothing. Not checked in game.

START TRANSACTION;

DROP TEMPORARY TABLE IF EXISTS `everlake_live_rates`;
CREATE TEMPORARY TABLE `everlake_live_rates` (`lid` int unsigned NOT NULL, `item` int unsigned NOT NULL, `chance` float NOT NULL,
  PRIMARY KEY (`lid`, `item`)) ENGINE=InnoDB;


-- the same item twice in one table: the sniff's row goes, the QuestieDB row stays and takes the live rate below
DELETE a FROM `creature_loot_template` a
JOIN `everlake_live_rates` r ON r.`lid` = a.`Entry` AND r.`item` = a.`Item`
JOIN `creature_loot_template` b ON b.`Entry` = a.`Entry` AND b.`ItemType` = 0 AND b.`Item` = a.`Item` AND b.`Comment` LIKE 'QuestieDB%'
WHERE a.`ItemType` = 0 AND a.`QuestRequired` = 0 AND a.`Comment` LIKE 'Forever live drop%';

UPDATE `creature_loot_template` l
JOIN `everlake_live_rates` r ON r.`lid` = l.`Entry` AND r.`item` = l.`Item`
SET l.`Chance` = r.`chance`
WHERE l.`ItemType` = 0 AND l.`QuestRequired` = 0 AND (l.`Comment` LIKE 'QuestieDB%' OR l.`Comment` LIKE 'Forever live drop%')
  AND l.`Chance` >= 3 * r.`chance` AND l.`Chance` - r.`chance` >= 0.3;

DROP TEMPORARY TABLE `everlake_live_rates`;

COMMIT;
